AiBotShowUnitNames = false --Will update units to reflect the order theyve been given
AiBotShowEnemyUnitNames = false --Will rename enemy units to reflect their ID and lifetime count
AiBotRunVeryFast = false --Game starts off at +15 speed if set to adjustable

--Detailed profiling config options
AiBotRunProfiling = false --If turning to true-part way through the game then also run ForkThread(AiBotProfiler.ProfilerActualTimePerTick); Records data on how long most functions are taking
AiBotProfilingIncludePerTick = false --if AiBotRunProfiling is true, then this determins whether will just do the detailed log of time taken for functions, or will also include the per tick results
AiBotProfilerIgnoreFirst2Seconds = true --Means logic relating to pathing generation gets ignored
AiBotRunMemoryProfiling = false --if this is true then every 60s will list out how much memory each file in AiBot is using
AiBotRunGamePerformanceCheck = false --Aug 22 profiling tourney profiling - Runs regardless of whether AiBot is active in the game, sends a log every second with how long it took to run that second and how many units are in the game.  Copy of same profiling available for Aibot (that was used in the profiling tourney)
--Simple profiling option:
AiBotRunSimpleProfiling = false --if this is true then will output time taken every 10s
